import collections
import json
from pathlib import Path
import statistics as s
import sys


def difference(a, b):
    return 200 * abs(a - b) / (a + b)


def analyze(data):
    cells = collections.defaultdict(lambda: collections.defaultdict(list))
    for run in data['runs']:
        cells[run['case'], run['concurrency']][run['engine']].append(run)
    output = {'completed': 'completed_at' in data, 'windows': len(data['runs']),
              'requests': sum(r['requests'] for r in data['runs']),
              'errors': sum(r['errors'] for r in data['runs']), 'groups': []}
    for (case, concurrency), engines in sorted(cells.items()):
        cell = {'case': case, 'concurrency': concurrency, 'engines': {}}
        for name, runs in engines.items():
            rounds = collections.defaultdict(list)
            for r in runs:
                rounds[r['round']].append(r)
            record = {'samples': len(runs), 'requests': sum(r['requests'] for r in runs),
                      'errors': sum(r['errors'] for r in runs)}
            for metric, gate in [('rps', 10), ('p99_ms', 20)]:
                values = [r[metric] for r in runs]
                cv = 100 * s.stdev(values) / s.mean(values) if len(values) > 1 else None
                pairs = [difference(rs[0][metric], rs[1][metric])
                         for _, rs in sorted(rounds.items()) if len(rs) == 2]
                record[metric] = {'median': s.median(values), 'min': min(values), 'max': max(values),
                                  'cv_percent': cv, 'aa_pair_symmetric_differences_percent': pairs,
                                  'repeatability_pass': len(pairs) == 3 and len(values) == 6
                                  and max(pairs) <= gate and cv <= gate and not record['errors']}
            for metric in ['server_cpu_us_per_request', 'peak_pss_kib', 'server_cpu_cores',
                           'client_cpu_cores', 'origin_cpu_cores']:
                record[metric + '_median'] = s.median(r[metric] for r in runs)
            cell['engines'][{'rgnix': 'pingora', 'candidate': 'hyper'}[name]] = record
        if set(cell['engines']) == {'pingora', 'hyper'}:
            p, h = cell['engines']['pingora'], cell['engines']['hyper']
            cell['hyper_rps_vs_pingora_percent'] = 100 * (h['rps']['median'] / p['rps']['median'] - 1)
            cell['hyper_p99_vs_pingora_percent'] = 100 * (h['p99_ms']['median'] / p['p99_ms']['median'] - 1)
            cell['throughput_gate_pass'] = all(v['rps']['repeatability_pass'] for v in [p, h])
            cell['p99_gate_pass'] = all(v['p99_ms']['repeatability_pass'] for v in [p, h])
            cell['rounds'] = []
            for round_id in sorted({r['round'] for rs in engines.values() for r in rs}):
                pair = {e: [r for r in rs if r['round'] == round_id] for e, rs in engines.items()}
                if all(len(rs) == 2 for rs in pair.values()):
                    cell['rounds'].append({'round': round_id,
                        'hyper_rps_vs_pingora_percent': 100 * (s.mean(r['rps'] for r in pair['candidate']) / s.mean(r['rps'] for r in pair['rgnix']) - 1),
                        'hyper_p99_vs_pingora_percent': 100 * (s.mean(r['p99_ms'] for r in pair['candidate']) / s.mean(r['p99_ms'] for r in pair['rgnix']) - 1)})
        output['groups'].append(cell)
    return output


if __name__ == '__main__':
    print(json.dumps(analyze(json.loads(Path(sys.argv[1]).read_text())), indent=2))
